import {
  type ElectronApplication,
  type Page,
  expect,
  test,
} from "@playwright/test";
import { type DaemonConnection, connectToDaemon } from "@frameshell/protocol";
import { launch, sandbox } from "./harness.js";
import { useTestBinaries } from "./media.js";
import { waitForIngest } from "./preview-probe.js";

// Audition dialog (ADR 0038) in the built app: two sound effects generated by the daemon (`sound.sfx`, as the agent
// would with `frameshell sound sfx`) are heard side by side from the Explorer: a spectrogram, loudness and the take's
// kind and seed per row, "Match loudness" bringing both to the quieter one, play/stop, and "Show in Explorer" selecting the file.
const box = sandbox("demo");

test.describe.configure({ mode: "serial" });

let app: ElectronApplication;
let page: Page;
let files: string[];

const row = (path: string) =>
  page
    .getByRole("treeitem", { name: path, exact: true })
    .getByRole("button")
    .first();
const dialog = () => page.getByTestId("audition-dialog");

test.beforeAll(async () => {
  // Fetching ffmpeg once and two takes on a busy machine.
  test.setTimeout(240_000);
  await useTestBinaries(box.configDir);
  ({ app, page } = await launch(box));
  // The app starts its daemon with the project; the socket can appear a moment after the boot screen is gone.
  let cli: DaemonConnection | undefined;
  await expect
    .poll(
      async () =>
        (cli = await connectToDaemon(box.socketPath, {
          client: "cli/e2e",
        }).catch(() => undefined)) !== undefined,
      { timeout: 60_000 },
    )
    .toBe(true);
  if (!cli) throw new Error("no daemon");
  try {
    const whoosh = await cli.request("sound.sfx", {
      cwd: box.projectDir,
      kind: "whoosh",
      seed: 1,
    });
    const pop = await cli.request("sound.sfx", {
      cwd: box.projectDir,
      kind: "pop",
      seed: 1,
    });
    files = [whoosh.file, pop.file].sort();
  } finally {
    cli.close();
  }
});

test.afterAll(async () => {
  await app?.close();
});

test("two selected sounds open side by side, with their loudness, take and spectrogram, and match in loudness", async () => {
  await row("assets").click();
  await row("assets/sound").click();
  await row(files[0]!).click();
  await row(files[1]!).click({
    modifiers: [process.platform === "darwin" ? "Meta" : "Control"],
  });
  await row(files[1]!).click({ button: "right" });
  await page.getByRole("menuitem", { name: "Audition 2 sounds…" }).click();

  await expect(dialog()).toBeVisible();
  const rows = dialog().getByTestId("audition-row");
  await expect(rows).toHaveCount(2, { timeout: 60_000 });
  await expect(rows.nth(0)).toHaveAttribute("data-asset", files[0]!);
  await expect(dialog().getByTestId("audition-spectrogram")).toHaveCount(2);
  await expect(dialog().getByTestId("audition-take")).toHaveText([
    /^pop · variant 1 · seed 1$/,
    /^whoosh · variant 1 · seed 1$/,
  ]);
  await expect(dialog().getByTestId("audition-lufs").first()).toHaveText(
    /^-\d+\.\d LUFS · peak -\d+\.\d dBTP$/,
  );
  await expect(dialog().getByTestId("audition-gain")).toHaveCount(0);

  await dialog().getByTestId("audition-match").check();
  await expect(dialog().getByTestId("audition-match-note")).toHaveText(
    /^Every sound plays at -\d+\.\d LUFS, the level of the quietest one\.$/,
  );
  const gains = await dialog().getByTestId("audition-gain").allTextContents();
  expect(gains).toHaveLength(2);
  // The quieter take keeps its level, the other comes down to it.
  expect(gains.filter((gain) => gain === "0.0 dB")).toHaveLength(1);
  expect(gains.filter((gain) => /^-\d+\.\d dB$/.test(gain))).toHaveLength(1);
  await dialog().getByTestId("audition-match").uncheck();
  await expect(dialog().getByTestId("audition-gain")).toHaveCount(0);
});

test("a row plays and stops, and Show in Explorer selects its file", async () => {
  test.setTimeout(240_000);
  for (const file of files) await waitForIngest(page, file);
  const play = dialog().getByTestId("audition-play").first();
  await expect(play).toBeEnabled();
  await play.click();
  await expect(play).toHaveAttribute("data-playing", "true");
  await play.click();
  await expect(play).toHaveAttribute("data-playing", "false");

  await dialog().getByTestId("audition-use").nth(1).click();
  await expect(dialog()).toHaveCount(0);
  await expect(row(files[1]!)).toHaveAttribute("data-picked", "true");
  await expect(row(files[0]!)).not.toHaveAttribute("data-picked", "true");
});

test("a folder's menu auditions the sounds in it, and Escape closes the dialog", async () => {
  await row("assets/sound").click({ button: "right" });
  await page
    .getByRole("menuitem", { name: "Audition the 2 sounds here…" })
    .click();
  await expect(dialog().getByTestId("audition-row")).toHaveCount(2);
  await page.keyboard.press("Escape");
  await expect(dialog()).toHaveCount(0);
});

test("music candidates play in the mix one at a time, in the preview only, and stop", async () => {
  const cli = await connectToDaemon(box.socketPath, { client: "cli/e2e" });
  try {
    // Two generated music takes, long enough to still play while the test switches between them.
    const take = (seed: number) =>
      cli.request("sound.music", {
        cwd: box.projectDir,
        preset: "minimal",
        length: 12,
        seed,
        place: false,
      });
    const [a, b] = await Promise.all([take(1), take(2)]);
    await cli.request("music.candidates", {
      cwd: box.projectDir,
      assets: [a.file, b.file],
    });
  } finally {
    cli.close();
  }
  const reader = await connectToDaemon(box.socketPath, { client: "cli/e2e" });
  const second = await reader
    .request("timeline.show", { cwd: box.projectDir })
    .then((shown) => shown.tracks.find((track) => track.name === "Music 2")?.id)
    .finally(() => reader.close());
  const head = page.locator(`.track-head[data-track="${second}"]`);
  await expect(head).toHaveCount(1);
  await head.click({ button: "right" });
  await page
    .getByRole("menuitem", { name: "Audition the 2 music candidates…" })
    .click();
  const mix = dialog().getByTestId("audition-in-mix");
  await expect(mix).toHaveCount(2);
  const playButton = page.locator(".preview-play");

  await mix.nth(1).click();
  await expect(mix.nth(1)).toHaveAttribute("data-playing", "true");
  await expect(mix.nth(1)).toHaveText("Stop the mix");
  await expect(playButton).toHaveClass(/playing/);
  // Another candidate takes over; the first stops.
  await mix.nth(0).click();
  await expect(mix.nth(0)).toHaveAttribute("data-playing", "true");
  await expect(mix.nth(1)).toHaveAttribute("data-playing", "false");

  await mix.nth(0).click();
  await expect(mix.nth(0)).toHaveAttribute("data-playing", "false");
  await expect(playButton).not.toHaveClass(/playing/);
  await dialog().getByTestId("audition-close").click();
  // Nothing was written: the candidates' tracks keep the mutes `music candidates` gave them.
  const cli2 = await connectToDaemon(box.socketPath, { client: "cli/e2e" });
  try {
    const shown = await cli2.request("timeline.show", { cwd: box.projectDir });
    const muted = Object.fromEntries(
      shown.tracks
        .filter((track) => /^Music \d$/.test(track.name ?? ""))
        .map((track) => [track.name, track.muted === true]),
    );
    expect(muted).toEqual({ "Music 1": false, "Music 2": true });
  } finally {
    cli2.close();
  }
});
